/**
 * External dependencies.
 */
import React, { createContext, useContext, useMemo, useState, useCallback, ReactNode } from 'react';

/**
 * WordPress dependencies.
 */
import { __ } from '@wordpress/i18n';
import { getQueryArg } from '@wordpress/url';
import { store as noticesStore } from '@wordpress/notices';
import { useDispatch } from '@wordpress/data';

declare global {
    interface Window {
        noptinWorkspace: {
            ajaxUrl: string;
            updatesNonce: string;
            plugins?: Record<string, Partial<PluginStatus>>;
            [ key: string ]: any;
        };
    }
}

type PluginInstallResponse = {
    success: boolean;
    data: {
        errorMessage?: string;
        pluginName?: string;
        activateUrl?: string;
        debug?: string[];
    };
};

const handleAjaxRequest = async ( bodyParams: Record<string, string> ) => {
    try {
        const response = await fetch( window.noptinWorkspace.ajaxUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            },
            body: new URLSearchParams( {
                _ajax_nonce: window.noptinWorkspace.updatesNonce,
                ...bodyParams,
            } ).toString(),
        } );

        if ( !response.ok ) {
            throw new Error( `HTTP Error: ${ response.status }` );
        }

        // Check if response is valid JSON
        const text = await response.text();
        try {
            return JSON.parse( text ) as PluginInstallResponse;
        } catch ( e ) {
            console.error( 'Invalid JSON received:', text );
            throw new Error( 'Server returned invalid response.' );
        }
    } catch ( error ) {
        console.error( 'AJAX Error:', error );
        return {
            success: false,
            data: {
                errorMessage: ( error as Error ).message || 'Unknown error occurred.',
            },
        };
    }
};

interface PluginStatus {
    /**
     * The plugin file name, e.g, 'plugin-folder/plugin-file.php'.
     */
    file_name: string;

    /**
     * The plugin name, e.g, 'Noptin Mailchimp'.
     */
    name: string;

    /**
     * Whether the plugin is active.
     */
    isActive: boolean;

    /**
     * Whether the plugin is installed.
     */
    isInstalled: boolean;

    /**
     * Checks if we are in the middle of installing or activating the plugin.
     */
    isInstalling?: boolean;

    /**
     * Any error message related to the plugin.
     */
    error?: string;
}

interface PluginsState {
    /**
     * Plugins by their slug.
     */
    [ pluginSlug: string ]: PluginStatus;
}

interface PluginsContextType {
    plugins: PluginsState;
    updatePlugin: ( slug: string, status: Partial<PluginStatus> ) => void;
    installPlugin: ( slug: string, thenUpdate?: boolean ) => Promise<boolean>;
    activatePlugin: ( slug: string, plugin: Partial<PluginStatus> ) => Promise<boolean>;
}

const PluginsContext = createContext<PluginsContextType | undefined>( undefined );

const getDefaultPluginStatus = (): PluginStatus => ( {
    name: '',
    file_name: '',
    isActive: false,
    isInstalled: false,
} );

export const PluginsProvider: React.FC<{ children: ReactNode }> = ( { children } ) => {
    const { createErrorNotice, createSuccessNotice } = useDispatch( noticesStore );
    const [ plugins, setPlugins ] = useState<PluginsState>( () => {
        const rawData = window.noptinWorkspace?.plugins;

        if ( !rawData || Array.isArray( rawData ) ) {
            return {};
        }

        return Object.fromEntries(
            Object.entries( rawData ).map( ( [ slug, data ] ) => ( [
                slug,
                {
                    ...data,
                    isInstalled: true,
                    isInstalling: false,
                    error: undefined,
                } as PluginStatus,
            ] ) )
        );
    } );

    const updatePlugin = useCallback( ( slug: string, status: Partial<PluginStatus> ) => {
        setPlugins( ( prev ) => {
            const currentStatus = prev[ slug ] || getDefaultPluginStatus();
            return {
                ...prev,
                [ slug ]: {
                    ...currentStatus,
                    ...status,
                },
            };
        } );
    }, [ setPlugins ] );

    const activatePlugin = useCallback( async ( slug: string, plugin: Partial<PluginStatus> ) => {

        // Guard clause: If we don't have a filename, we can't activate
        if ( !plugin.file_name || !plugin.name ) {
            updatePlugin( slug, { error: 'Cannot activate: Plugin file not found.' } );
            return false;
        }

        updatePlugin( slug, { isInstalling: true, error: undefined } );

        const response = await handleAjaxRequest( {
            action: 'noptin_onboarding_ajax_activate_plugin',
            slug,
            plugin: plugin.file_name,
            name: plugin.name,
        } );

        if ( !response.success ) {
            updatePlugin( slug, {
                error: response.data.errorMessage || 'Failed to activate plugin.',
                isInstalling: false,
            } );

            createErrorNotice(
                response.data.errorMessage || 'Failed to activate plugin.',
                {
                    type: 'snackbar',
                }
            );
        } else {
            updatePlugin( slug, {
                isInstalled: true,
                isActive: true,
                isInstalling: false,
            } );
        }
        return response.success;
    }, [ updatePlugin, createErrorNotice ] );

    const installPlugin = useCallback( async ( slug: string, thenUpdate?: boolean ) => {
        updatePlugin( slug, { isInstalling: true, error: undefined } );

        const response = await handleAjaxRequest( {
            action: 'noptin_onboarding_ajax_install_plugin',
            slug,
        } );

        if ( !response.success ) {
            updatePlugin( slug, {
                error: response.data.errorMessage || 'Failed to install plugin.',
                isInstalling: false,
            } );

            createErrorNotice(
                response.data.errorMessage || 'Failed to install plugin.',
                {
                    type: 'snackbar',
                }
            );
        } else {
            const toUpdate: Partial<PluginStatus> = {
                isInstalled: true,
                isInstalling: false,
            };

            if ( response.data.pluginName ) {
                toUpdate.name = response.data.pluginName;
            }

            const fileName = getQueryArg( response.data.activateUrl || '', 'plugin' ) || '';
            if ( fileName ) {
                toUpdate.file_name = fileName as string;
            }

            updatePlugin( slug, toUpdate );

            if ( Array.isArray( response.data.debug ) && response.data.debug.length > 0 ) {
                console.log( 'Plugin Install Debug Info:', response.data.debug );
                createSuccessNotice(
                    response.data.debug[ response.data.debug.length - 1 ],
                    {
                        type: 'snackbar',
                    }
                );
            }

            if ( thenUpdate && toUpdate.name && toUpdate.file_name ) {
                return activatePlugin( slug, { ...toUpdate } );
            }
        }
        return false;
    }, [ activatePlugin, createErrorNotice, createSuccessNotice ] );

    return (
        <PluginsContext.Provider value={ { plugins, updatePlugin, installPlugin, activatePlugin } }>
            { children }
        </PluginsContext.Provider>
    );
};

export const usePlugin = ( pluginSlug: string ) => {
    const context = useContext( PluginsContext );

    if ( !context ) {
        throw new Error( 'usePlugin must be used within a PluginsProvider' );
    }

    const { plugins, installPlugin, activatePlugin } = context;
    const pluginStatus = plugins[ pluginSlug ] || {
        file_name: '',
        isActive: false,
        isInstalled: false,
    };

    return useMemo(
        () => {
            const activate = () => activatePlugin( pluginSlug, pluginStatus );
            const install = ( thenUpdate?: boolean ) => installPlugin( pluginSlug, thenUpdate );
            let actionButton;

            if ( pluginStatus.isActive ) {
                actionButton = {
                    variant: 'primary',
                    text: __( 'Active', 'newsletter-optin-box' ),
                    className: 'noptin-components-button__green',
                    disabled: true,
                }
            } else if ( pluginStatus.isInstalled ) {
                actionButton = {
                    variant: 'primary',
                    text: pluginStatus.isInstalling ? __( 'Activating...', 'newsletter-optin-box' ) : __( 'Activate', 'newsletter-optin-box' ),
                    isBusy: pluginStatus.isInstalling,
                    onClick: activate,
                    className: 'noptin-components-button__pink',
                    disabled: pluginStatus.isInstalling,
                };
            } else {
                actionButton = {
                    variant: 'primary',
                    text: pluginStatus.isInstalling ? __( 'Installing...', 'newsletter-optin-box' ) : __( 'Install', 'newsletter-optin-box' ),
                    isBusy: pluginStatus.isInstalling,
                    // Install then update.
                    onClick: () => install( true ),
                    disabled: pluginStatus.isInstalling,
                };
            }

            return {
                ...pluginStatus,
                install: install,
                activate: activate,
                actionButton,
            };
        },
        [ pluginStatus, installPlugin, activatePlugin, pluginSlug ]
    );
};
