import { Spinner, __experimentalHStack as HStack, __experimentalText as Text } from '@wordpress/components';

/**
 * Internal dependencies
 */
import { Addons } from './addons';
import { License } from './license';
import { useLicense } from './license/provider';
import { AgencyControls } from './agency';

const initialSettings: Record<string, any> = window.noptinWorkspace?.options || {};
const hideLicense = initialSettings?.visibility?.hide_license && initialSettings?.visibility?.last_edited_by && window.noptinWorkspace?.user_id !== initialSettings.visibility.last_edited_by;
export const Workspace = () => {
	const { isCheckingLicenseKey } = useLicense();

	if ( isCheckingLicenseKey ) {
		return (
			<HStack justify="flex-start" wrap>
				<Spinner />
				{ !hideLicense && ( <Text>Checking license key...</Text> ) }
			</HStack>

		)
	}

	if ( hideLicense ) {
		return <Addons disableModal />;
	}

	return (
		<>
			<License />
			<Addons />
			<AgencyControls />
		</>
	);
}
