/**
 * External dependencies
 */
import React from 'react';

/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import {
	__experimentalText as Text,
	__experimentalVStack as VStack,
} from '@wordpress/components';

/**
 * HizzleWP dependencies.
 */
import { Interface, Header, Footer } from '@hizzlewp/interface';
import { ErrorBoundary } from '@hizzlewp/components';

/**
 * Local dependancies.
 */
import { Workspace } from './workspace';
import { LicenseProvider } from './license/provider';
import { PluginsProvider } from './addons/provider';
import { EditorNotices, EditorSnackbars } from './notices';

const theFooter = (
	<Footer>
		<a href="https://wordpress.org/support/plugin/newsletter-optin-box/reviews/?filter=5" target="_blank" rel="noreferrer">
			<Text size={ 14 } variant="muted">
				Thank you for using Noptin. Please leave us a review 🌟
			</Text>
		</a>
	</Footer>
);

const theContent = (
	<VStack spacing={ 6 } style={ { padding: 20, maxWidth: '56rem', margin: '0 auto' } }>
		<ErrorBoundary>
			<EditorSnackbars />
		</ErrorBoundary>
		<ErrorBoundary>
			<EditorNotices />
		</ErrorBoundary>
		<ErrorBoundary>
			<Workspace />
		</ErrorBoundary>
	</VStack>
);

export default function Layout( { brand, actions } ): React.ReactNode {

	const header = (
		<ErrorBoundary>
			<Header brand={ brand } actions={ actions } />
		</ErrorBoundary>
	);

	return (
		<LicenseProvider licenseKey={ window.noptinWorkspace.license_key }>
			<PluginsProvider>
				<Interface
					isDistractionFree={ false }
					header={ header }
					content={ theContent }
					footer={ theFooter }
				/>
			</PluginsProvider>
		</LicenseProvider>
	);
}
