/**
 * External dependencies.
 */
import React, { createContext, useContext, useMemo, useState, useCallback, useRef, useEffect } from 'react';

/**
 * WordPress dependencies.
 */
import apiFetch from '@wordpress/api-fetch';
import { __ } from '@wordpress/i18n';
import { addQueryArgs } from '@wordpress/url';
import { store as noticesStore } from '@wordpress/notices';
import { useDispatch } from '@wordpress/data';

export interface LicenseDetails {
    /**
     * The full license key.
     */
    license_key: string;

    /**
     * The license key as asterisks, partially masked for security.
     */
    license_key_ast: string;

    /**
     * The product ID for this license key.
     */
    product_id: number | null;

    /**
     * The product name for this license key.
     */
    product_name: string | null;

    /**
     * The product SKU for this license key.
     */
    product_sku: string | null;

    /**
     * The user ID associated with this license key.
     */
    user_id: number;

    /**
     * The email address associated with this license key.
     */
    email: string;

    /**
     * The first name associated with this license key.
     */
    first_name: string;

    /**
     * The last name associated with this license key.
     */
    last_name: string;

    /**
     * The display name associated with this license key.
     */
    display_name: string;

    /**
     * Whether the license key is currently active.
     */
    is_active: boolean;

    /**
     * Whether the license key has expired.
     */
    has_expired: boolean;

    /**
     * The date the license key was created.
     */
    date_created: string;

    /**
     * The date the license key expires. Empty for lifetime licenses.
     */
    date_expires: string;

    /**
     * The maximum number of activations allowed for this license key.
     */
    max_activations: number;

    /**
     * A record of activations with the site as the key and the activation date as the value.
     */
    activations: Record<string, string>;

    /**
     * A string representation of the activations, e.g., "7 / 10".
     */
    the_activations: string;

    /**
     * Whether the license key is currently active on the site.
     */
    is_active_on_site: boolean;
}

export interface LicenseError {
    code: string;
    message: string;
    data?: {
        status?: number;
    }
}

export type LicenseResponse =
    | { ok: true; license: LicenseDetails }
    | { ok: false; error: LicenseError };

// Cache to avoid redundant API calls for the same license key during a session, e.g, when component re-renders.
const LICENSE_DETAILS: Record<string, LicenseResponse> = {};

const getLicenseCheckURL = ( licenseKey: string ) => {
    return addQueryArgs(
        `https://my.noptin.com/wp-json/hizzle/v1/licenses/${ licenseKey }/`,
        {
            // @ts-ignore - injected via Menu.php
            website: window.noptinWorkspace.home_url,
        }
    );
}

const getLicenseKeyDetails = async ( licenseKey: string ) => {
    const url = getLicenseCheckURL( licenseKey );

    if ( LICENSE_DETAILS[ url ] ) {
        return LICENSE_DETAILS[ url ];
    }

    try {
        const response = await fetch( url, {
            headers: {
                Accept: 'application/json',
            },
        } );

        const json = await response.json();

        if ( !response.ok ) {
            console.error( 'License validation failed:', json );

            const result: LicenseResponse = {
                ok: false,
                error: json as LicenseError,
            };
            LICENSE_DETAILS[ url ] = result;
            return result;
        }

        const result: LicenseResponse = {
            ok: true,
            license: ( json as { license: LicenseDetails } ).license,
        };

        LICENSE_DETAILS[ url ] = result;
        return result;
    } catch ( e ) {
        const result: LicenseResponse = {
            ok: false,
            error: {
                code: 'network_error',
                message: 'Failed to validate license key',
                data: { status: 0 },
            },
        };

        // Don't cache this.
        // LICENSE_DETAILS[ url ] = result;
        return result;
    }
};

const activateLicenseKey = async ( license_key: string ) => {
    // Activate via API.
    const data = await apiFetch<{ message: string; success: true; data: any; }>( {
        path: '/noptin/v1/license/activate',
        method: 'POST',
        data: {
            license_key,
        },
    } );

    // Delete checks cache.
    const url = getLicenseCheckURL( license_key );
    delete LICENSE_DETAILS[ url ];

    return data as {
        message: string;
        success: true;
        data: any;
        info: LicenseDetails;
    }
};

const deactivateLicenseKey = async ( license_key: string ) => {
    // Deactivate via API.
    const data = await apiFetch<{ message: string; success: true; }>( {
        path: '/noptin/v1/license/deactivate',
        method: 'DELETE',
    } );

    // Delete checks cache.
    const url = getLicenseCheckURL( license_key );
    delete LICENSE_DETAILS[ url ];

    return data;
};

/**
 * Interface for the license context.
 */
interface LicenseContextProps {

    /**
     * The current license key.
     */
    licenseKey: string;

    /**
     * Set the license key.
     */
    setLicenseKey: ( licenseKey: string ) => void;

    /**
     * Whether the license key is currently being checked.
     */
    isCheckingLicenseKey: boolean;

    /**
     * License info.
     */
    licenseInfo?: LicenseDetails;

    /**
     * Any error associated with the current license key.
     */
    error?: string;

    /**
     * Any error associated with the current license key.
     */
    checkedLicenseKey?: string;

    /**
     * Activate the license key.
     */
    onActivateLicenseKey: () => Promise<void>;

    /**
     * Whether the license key is currently being activated.
     */
    isActivating: boolean;

    /**
     * Deactivate the license key.
     */
    onDeactivateLicenseKey: () => Promise<void>;

    /**
     * Whether the license key is currently being deactivated.
     */
    isDeactivating: boolean;
}

/**
 * Context for license.
 */
const LicenseContext = createContext<LicenseContextProps>( {
    licenseKey: '',
    setLicenseKey: () => { },
    onActivateLicenseKey: async () => { },
    onDeactivateLicenseKey: async () => { },
    isDeactivating: false,
    isActivating: false,
    isCheckingLicenseKey: false,
} );

/**
 * Custom hook to access the context.
 */
export const useLicense = () => useContext( LicenseContext );

/**
 * Provider component for license.
 */
export interface LicenseProviderProps {
    /**
     * License info.
     */
    info?: LicenseDetails;

    /**
     * The current license key.
     */
    licenseKey: string;

    /**
     * Any error associated with the current license key.
     */
    error?: string;

    /**
     * The children.
     */
    children: React.ReactNode;
}

/**
 * Provider component for license.
 */
export const LicenseProvider: React.FC<LicenseProviderProps> = ( {
    info: currentInfo,
    licenseKey: currentLicenseKey,
    error: currentError,
    children,
} ) => {

    // License key state management
    const [ licenseKey, setLicenseKey ] = useState<string | undefined>( currentLicenseKey );
    const [ checkedLicenseKey, setCheckedLicenseKey ] = useState<string | undefined>( currentLicenseKey );
    const [ isCheckingLicenseKey, setIsCheckingLicenseKey ] = useState<boolean>( true );
    const [ licenseInfo, setLicenseInfo ] = useState<LicenseDetails | null>( currentInfo?.license_key ? currentInfo : null );

    // Activation state.
    const [ isActivating, setIsActivating ] = useState<boolean>( false );
    const [ isDeactivating, setIsDeactivating ] = useState<boolean>( false );
    const [ error, setError ] = useState<string | undefined>( currentError );

    const { createSuccessNotice } = useDispatch( noticesStore );

    // Checks the license key remotely.
    useEffect( () => {
        let isMounted = true;

        if ( checkedLicenseKey ) {
            setIsCheckingLicenseKey( true );
            getLicenseKeyDetails( checkedLicenseKey || '' )
                .then( ( response ) => {
                    if ( !isMounted ) return;

                    if ( response.ok ) {
                        setLicenseInfo( response.license );
                    } else {
                        setError( response.error.message || 'Failed to fetch license details' );
                    }
                } )
                .catch( ( e ) => {
                    console.error( e );
                    if ( isMounted ) {
                        setError( e?.message || 'Failed to check license key' );
                    }
                } ).finally( () => {
                    if ( isMounted ) {
                        setIsCheckingLicenseKey( false );
                    }
                } );
        } else {
            setLicenseInfo( null );
            setIsCheckingLicenseKey( false );
        }

        return () => {
            isMounted = false;
        };
    }, [ checkedLicenseKey ] );

    /**
     * Reset error when license key changes.
     */
    useEffect( () => {
        setError( undefined );
    }, [ licenseKey ] );

    /**
     * Saves the license key.
     */
    const onActivateLicenseKey: React.FormEventHandler<HTMLFormElement> = useCallback( async ( e ) => {
        e?.preventDefault();

        try {
            // Show loading state for activation process.
            setIsActivating( true );
            setError( undefined );

            if ( !licenseKey ) {
                throw new Error( 'Please enter a valid license key.' );
            }

            const result = await activateLicenseKey( licenseKey || '' );

            createSuccessNotice(
                'License activated successfully.',
                {
                    type: 'snackbar',
                }
            );

            // Update the checked license key to trigger re-fetching license details and showing the license info.
            setCheckedLicenseKey( licenseKey );
        } catch ( e: any ) {
            setError( e?.message || 'Failed to activate license key' );
        } finally {
            setIsActivating( false );
        }
    }, [ licenseKey ] );

    const onDeactivateLicenseKey = useCallback( async () => {
        try {
            // Show loading state for deactivation process.
            setIsDeactivating( true );
            setError( undefined );

            const result = await deactivateLicenseKey( licenseKey || '' );

            createSuccessNotice(
                'License deactivated successfully.',
                {
                    type: 'snackbar',
                }
            );

            setCheckedLicenseKey( '' );
            setLicenseKey( '' );
            setLicenseInfo( null );
        } catch ( e: any ) {
            setError( e?.message || 'Failed to deactivate license key' );
        } finally {
            setIsDeactivating( false );
        }
    }, [ licenseKey ] );

    const prepared = useMemo( () => {
        return {
            checkedLicenseKey,
            error,
            isDeactivating,
            isActivating,
            onActivateLicenseKey,
            onDeactivateLicenseKey,
            licenseInfo,
            isCheckingLicenseKey,
            licenseKey: licenseKey || '',
            setLicenseKey,
        } as LicenseContextProps;
    }, [
        checkedLicenseKey,
        error,
        isDeactivating,
        isActivating,
        onActivateLicenseKey,
        onDeactivateLicenseKey,
        licenseInfo,
        isCheckingLicenseKey,
        licenseKey,
        setLicenseKey,
    ] );

    const isSaving = isActivating || isDeactivating || isCheckingLicenseKey;
    const style: React.CSSProperties = useMemo( () => {
        return {
            pointerEvents: isSaving ? 'none' : 'auto',
            cursor: isSaving ? 'wait' : 'auto',
        };
    }, [ isSaving ] );

    return (
        <LicenseContext.Provider value={ prepared }>
            <div style={ style }>
                { children }
            </div>
        </LicenseContext.Provider>
    );
};
