/**
 * External dependencies.
 */
import React, { useMemo } from 'react';

/**
 * WordPress dependencies.
 */
import {
	__experimentalVStack as VStack,
	__experimentalHeading as Heading,
	__experimentalText as Text,
} from '@wordpress/components';

/**
 * Hizzle dependencies.
 */
import { Setting, SettingProps } from '@hizzlewp/components';

export const useSettings = ( disabled: boolean, settings: Record<string, SettingProps[ 'setting' ]> ) => useMemo( () => {
	if ( !disabled ) {
		return settings;
	}

	return Object.fromEntries(
		Object
			.entries( settings )
			.map( ( [ key, setting ] ) => [ key, { ...setting, disabled: true } ] )
	)
}, [ disabled, settings ] );

export type WhiteLabelProps = {
	isDisabled: boolean,
	saved: SettingProps[ 'saved' ],
	setAttributes: SettingProps[ 'setAttributes' ],
}

const SETTINGS: Record<string, SettingProps[ 'setting' ]> = {
	'white_label.name': {
		el: 'input',
		type: 'text',
		label: 'Plugin Name',
		placeholder: 'e.g. Agency Mailer',
	},
	'white_label.icon': {
		el: 'input',
		type: 'text',
		label: 'Menu Icon',
		placeholder: 'e.g. dashicons-forms',
		description: 'Can be a URL, dashicon class, or a base64-encoded SVG using a data URI.'
	},
	'white_label.logo': {
		el: 'input',
		type: 'text',
		label: 'Plugin Icon URL',
		placeholder: 'e.g. https://youragency.com/icon.png',
		description: 'Shown at the top of all Noptin pages',
	},
	'white_label.support_url': {
		el: 'input',
		type: 'text',
		label: 'Support URL',
		placeholder: 'e.g. https://youragency.com/support',
	},
};

/**
 * Rebrand the Noptin interface for your clients.
 */
export const WhiteLabel: React.FC<WhiteLabelProps> = ( { saved, setAttributes, isDisabled } ) => {
	const settings = useSettings( isDisabled, SETTINGS );

	return (
		<>
			<VStack spacing={ 1 }>
				<Heading size={ 16 } level={ 3 }>White Label</Heading>
				<Text variant="muted">Rebrand the Noptin interface for your clients.</Text>
			</VStack>
			{ Object.entries( settings ).map( ( [ key, setting ] ) => (
				<Setting
					key={ key }
					settingKey={ key }
					setting={ setting }
					saved={ saved }
					setAttributes={ setAttributes }
				/>
			) ) }
		</>
	);
};
