/**
 * External dependencies.
 */
import React from 'react';

/**
 * Hizzle dependencies.
 */
import { Setting, SettingProps } from '@hizzlewp/components';

/**
 * Internal dependencies.
 */
import { WhiteLabelProps, useSettings } from './white-label';

const SETTINGS: Record<string, SettingProps[ 'setting' ]> = {
	'visibility.hide_license': {
		el: 'input',
		type: 'checkbox',
		label: 'Hide license details',
		description: 'Enable this to hide your license details and agency controls from other admins, such as your clients.'
	},
	'visibility.hide_workspace': {
		el: 'input',
		type: 'checkbox',
		label: 'Hide this page entirely',
		description: 'Go a step further and hide this entire page from other admins, such as your clients.',
		conditions: [ {
			key: 'visibility.hide_license',
			value: true,
		} ]
	},
	'visibility.split_email_menu': {
		el: 'input',
		type: 'checkbox',
		label: 'Expand "Email Campaigns" menu',
		description: 'Displays Newsletters, Automated Emails, Sequences, and Templates as individual items in the admin menu sidebar.',
	},
	'templates.hide_cloud': {
		el: 'input',
		type: 'checkbox',
		label: 'Hide built-in email templates',
		description: 'Enable this to hide the pre-built email templates that come with Noptin from your clients.',
	},
	'templates.hide_custom': {
		el: 'input',
		type: 'checkbox',
		label: 'Hide custom email templates',
		description: 'Enable this to hide custom email templates that you or your clients have manually created.',
	},
};

/**
 * Configure the admin menu visibility.
 */
export const Visibility: React.FC<WhiteLabelProps> = ( { saved, setAttributes, isDisabled } ) => {
	const settings = useSettings( isDisabled, SETTINGS );

	return (
		<>
			{ Object.entries( settings ).map( ( [ key, setting ] ) => (
				<Setting
					key={ key }
					settingKey={ key }
					setting={ setting }
					saved={ saved }
					setAttributes={ setAttributes }
				/>
			) ) }
		</>
	);
};
