/**
 * External dependencies.
 */
import { useState, useEffect } from 'react';
import { ISetting } from '@hizzlewp/components';

/**
 * WordPress dependencies.
 */
import { __ } from '@wordpress/i18n';
import {
    __experimentalVStack as VStack,
    __experimentalGrid as Grid,
    __experimentalHeading as Heading,
    Button,
    SearchControl,
    Modal,
    Card,
    CardBody,
    CardHeader,
    CardFooter,
    Tooltip,
} from '@wordpress/components';

/**
 * HizzleWP dependencies
 */
import {
    ErrorBoundary,
} from '@hizzlewp/components';

/**
 * Local dependencies.
 */
import { Addon, AddonProps } from './addon';
import { AddonSettings, getAddonSettings, fetchAddonSettings } from './settings';

const CONNECTIONS: AddonProps[] = window.noptinWorkspace?.connections || [];
const INTEGRATIONS: AddonProps[] = window.noptinWorkspace?.integrations || [];
const PLUGINS = [
    {
        slug: 'addons-pack',
        name: 'Addons Pack',
        description: 'Enable email sequences/courses, coupon codes, and more premium features.',
        icon: {
            icon: 'email',
            fill: '#e91e63',
        },
        plugin_url: 'https://noptin.com/ultimate-addons-pack/',
    },
    ...INTEGRATIONS,
    ...CONNECTIONS,
];
const COMPACT_THRESHOLD = 5;

export const TipPopover: React.FC<{ tip: string }> = ( { tip } ) => {
    return (
        <Tooltip delay={ 0 } text={ tip }>
            <Button
                size="compact"
                icon="info"
                style={ { color: '#6b7280' } }
            />
        </Tooltip>
    );
};

/*
 * Displays available addons.
 *
 */
export const Addons = ( { disableModal }: { disableModal?: boolean } ) => {
    const [ isModalOpen, setIsModalOpen ] = useState( false );
    const [ searchQuery, setSearchQuery ] = useState( '' );
    const [ selected, setSelected ] = useState<AddonProps | null>( null );
    const [ fields, setFields ] = useState<Record<string, ISetting>>( {} );
    useEffect( () => {
        let cancelled = false;
        fetchAddonSettings().then( ( result ) => {
            if ( !cancelled ) setFields( result );
        } ).catch( () => {} );
        return () => { cancelled = true; };
    }, [] );
    const configure = ( plugin: AddonProps ) => {
        setSelected( plugin );
        setIsModalOpen( true );
    };
    const addon = ( plugin: AddonProps ) => (
        <Addon { ...plugin } isCompact
            onActivated={ () => configure( plugin ) }
            onConfigure={ getAddonSettings( fields, plugin.slug ) ? () => configure( plugin ) : undefined } />
    );
    const showCompact = PLUGINS.length > COMPACT_THRESHOLD && !disableModal;
    const normalizedSearch = searchQuery.trim().toLowerCase();
    const filteredPlugins = normalizedSearch
        ? PLUGINS.filter( ( plugin ) =>
            [ plugin.name, plugin.slug, plugin.description ].some(
                ( value ) => value && value.toLowerCase().includes( normalizedSearch )
            )
        )
        : PLUGINS;
    const toShow = showCompact ? filteredPlugins.slice( 0, COMPACT_THRESHOLD - 1 ) : filteredPlugins;

    const openModal = () => setIsModalOpen( true );
    const closeModal = () => {
        setIsModalOpen( false );
        setSelected( null );
        setSearchQuery( '' );
    };

    return (
        <>
            <Card isBorderless elevation={ 2 }>
                <CardHeader justify="flex-start">
                    <Heading level={ 4 }>Add-ons</Heading>
                    <TipPopover tip="Noptin stays lightweight by letting you only install the features you need." />
                </CardHeader>
                <CardBody>
                    <VStack spacing={ 3 }>
                        { ( disableModal && PLUGINS.length > COMPACT_THRESHOLD ) && (
                            <SearchControl
                                __next40pxDefaultSize
                                __nextHasNoMarginBottom
                                label="Search add-ons"
                                placeholder="Search add-ons"
                                className="noptin-addons-search"
                                value={ searchQuery }
                                onChange={ setSearchQuery }
                            />
                        ) }
                        <Grid className="template-grid" templateColumns="repeat(auto-fill, minmax(300px, 1fr))" gap={ 4 }>
                            { toShow.map( ( plugin ) => (
                                <ErrorBoundary key={ plugin.slug }>
                                    { addon( plugin ) }
                                </ErrorBoundary>
                            ) ) }
                        </Grid>
                    </VStack>
                </CardBody>
                { showCompact && (
                    <CardFooter>
                        <Button
                            variant="primary"
                            onClick={ openModal }
                        >
                            { `View all ${ PLUGINS.length } add-ons` }
                        </Button>
                    </CardFooter>
                ) }
            </Card>
            { isModalOpen && (
                <Modal
                    title={ selected ? `${ selected.name } Settings` : 'Install Add-ons' }
                    onRequestClose={ closeModal }
                    isFullScreen={ !selected }
                    size={ selected ? 'medium' : undefined }
                    className={ selected ? 'noptin-addon-settings-modal' : undefined }
                >
                    { selected ? (
                        <ErrorBoundary>
                            <AddonSettings key={ selected.slug } slug={ selected.slug } onLoaded={ setFields }
                                onEmpty={ () => setSelected( null ) } onClose={ () => setSelected( null ) } />
                        </ErrorBoundary>
                    ) : <VStack spacing={ 4 }>
                        <SearchControl
                            __next40pxDefaultSize
                            __nextHasNoMarginBottom
                            label="Search add-ons"
                            placeholder="Search add-ons"
                            className="noptin-addons-search"
                            value={ searchQuery }
                            onChange={ setSearchQuery }
                        />
                        { filteredPlugins.length > 0 ? (
                            <Grid className="template-grid" templateColumns="repeat(auto-fill, minmax(300px, 1fr))" gap={ 4 }>
                                { filteredPlugins.map( ( plugin ) => (
                                    <ErrorBoundary key={ plugin.slug }>
                                        { addon( plugin ) }
                                    </ErrorBoundary>
                                ) ) }
                            </Grid>
                        ) : (
                            <p>No add-ons match your search.</p>
                        ) }
                    </VStack> }
                </Modal>
            ) }
        </>
    );
}
