import React from 'react';

import {
	Spinner,
	__experimentalHStack as HStack,
	__experimentalText as Text,
} from '@wordpress/components';

import { useLicense } from './provider';
import { Activate } from './activate';
import { LicenseInfo } from './info';

export const License: React.FC = () => {
	const { checkedLicenseKey, isActivating, error, isCheckingLicenseKey, licenseInfo } = useLicense();

	// If we don't have a license key yet, or we're in the process of activating, or there's an error, show the input form.
	if ( !checkedLicenseKey || isActivating || error ) {
		return <Activate />
	}

	if ( isCheckingLicenseKey || !licenseInfo ) {
		return (
			<HStack justify="flex-start" wrap>
				<Spinner />
				<Text>Checking license key...</Text>
			</HStack>

		)
	}

	return <LicenseInfo />;
}
