/**
 * External dependencies
 */
import React from 'react';

/**
 * WordPress dependencies
 */
import {
	Card,
	CardHeader,
	CardBody,
	CardFooter,
	__experimentalText as Text,
	__experimentalHeading as Heading,
	__experimentalHStack as HStack,
	__experimentalVStack as VStack,
	Button,
	FlexBlock,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';

/**
 * HizzleWP dependencies.
 */
import { ErrorBoundary, ImageOrIcon, ImageOrIconProps } from '@hizzlewp/components';

/**
 * Local dependencies.
 */
import { usePlugin } from './provider';
import { useLicense } from '../license/provider';

export interface AddonProps {
	slug: string;
	name: string;
	description?: string;
	icon?: ImageOrIconProps[ 'image' ];

	/**
	 * The plugin home page.
	 */
	plugin_url: string;

	/**
	 * Whether the plugin is free.
	 */
	isFree?: boolean;

	/**
	 * Whether to display compactly.
	 */
	isCompact?: boolean;
	onActivated?: () => void;
	onConfigure?: () => void;
}

/*
 * Displays a given addon.
 *
 */
export const Addon = ( { slug, name, description, icon, plugin_url, isFree, isCompact, onActivated, onConfigure }: AddonProps ): React.ReactNode => {
	const { error, actionButton: pluginButton, isActive, isInstalled, install, activate } = usePlugin( `noptin-${ slug }` );
	const actionButton = ( isFree || isActive ) && onConfigure ? {
		variant: 'primary',
		text: __( 'Settings', 'newsletter-optin-box' ),
		onClick: onConfigure,
	} : {
		...pluginButton,
		onClick: async () => {
			const activated = await ( isInstalled ? activate() : install( true ) );
			if ( activated ) onActivated?.();
		},
	};
	const className = `noptin-addon noptin-addon__${ slug } ${ error ? 'noptin-addon--error' : '' }`;
	if ( isCompact ) {
		return (
			<HStack spacing={ 4 } className={ `${className} noptin-addon--compact` } style={ { padding: '12px', border: '1px solid #ddd', borderRadius: '4px', maxWidth: '100%' } }>
				{ icon && <div style={ { flexShrink: 0 } }><ImageOrIcon image={ icon } alt={ name } /></div> }
				<VStack style={ { flexGrow: 1 } } spacing={ 0 }>
					<HStack as={ FlexBlock } justify="flex-start" spacing={ 0 } expanded={ false } wrap>
						<Text weight={ 600 }>{ name }</Text>
						{ plugin_url && (
							<Button
								href={ plugin_url }
								target="_blank"
								label={ __( 'Learn more', 'newsletter-optin-box' ) }
								size="compact"
								icon="info"
								style={ { color: '#6b7280' } }
								showTooltip
							/>
						) }
					</HStack>
					{ ( error || description ) && (
						<Text size="small" variant={ error ? undefined : 'muted' } isDestructive={ !!error } truncate numberOfLines={ isCompact ? 1 : undefined }>
							{ error || description }
						</Text>
					) }
				</VStack>
				<div style={ { flexShrink: 0 } }>
					<PrimaryButton isFree={ isFree && !onConfigure } isActive={ isActive || isFree } actionButton={ actionButton } />
				</div>
			</HStack>
		);
	}

	return (
		<Card className={ `${className} noptin-addon--card` } variant="tertiary" size="small">
			<CardHeader>
				<Heading level={ 4 } numberOfLines={ 1 }>
					{ name }
				</Heading>
				{ icon && <ImageOrIcon image={ icon } alt={ name } /> }
			</CardHeader>
			{ ( error || description ) && (
				<CardBody>
					<Text as="p" variant={ error ? undefined : 'muted' } isDestructive={ !!error } numberOfLines={ isCompact ? 1 : undefined }>
						{ error || description }
					</Text>
				</CardBody>
			) }
			<CardFooter isBorderless>
				{ plugin_url && (
					<Button
						variant="secondary"
						href={ plugin_url }
						target="_blank"
						text={ __( 'Learn more', 'newsletter-optin-box' ) }
						size="small"
					/>
				) }
				<PrimaryButton isFree={ isFree && !onConfigure } isActive={ isActive || isFree } actionButton={ actionButton } />
			</CardFooter>
		</Card >
	);
}

const PrimaryButton: React.FC<{ actionButton: any, isFree?: boolean, isActive?: boolean }> = ( { isFree, isActive, actionButton } ) => {
	const { licenseInfo } = useLicense();
	const hasLicense = !licenseInfo?.has_expired && licenseInfo?.is_active_on_site;

	if ( isFree ) {
		return (
			<Button
				variant="primary"
				text={ __( 'Active', 'newsletter-optin-box' ) }
				className="noptin-components-button__green"
				size="small"
				disabled
			/>
		)
	}

	if ( hasLicense || isActive ) {
		return <Button size="small" { ...actionButton } />
	}

	return (
		<Button
			variant="primary"
			text={ __( 'Premium', 'newsletter-optin-box' ) }
			icon="lock"
			size="small"
			disabled
		/>
	);
}
