import React, { useEffect, useState } from 'react';
import apiFetch from '@wordpress/api-fetch';
import { Button, Notice, Spinner, __experimentalVStack as VStack } from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { Setting, ISetting } from '@hizzlewp/components';

export const settingsPath = '/noptin/v1/settings/integrations/main';

export const fetchAddonSettings = async () => {
    try {
        return await apiFetch<Record<string, ISetting>>( { path: settingsPath } );
    } catch ( error ) {
        if ( error.code === 'invalid_section_slug' ) return {};
        throw error;
    }
};

export const getAddonSettings = ( fields: Record<string, ISetting>, slug: string ) => {
    const key = `settings_section_${ slug.replace( /-/g, '_' ) }`;
    const panel = fields[ key ];
    // Ignore the catalog's placeholder asking users to install the connection.
    if ( !panel?.settings || panel.settings[ `noptin_${ slug.replace( /-/g, '_' ) }_install` ] ) return undefined;
    return Object.keys( panel.settings ).length ? panel : undefined;
};

// Also apply to fields inside horizontal groups and other nested settings.
const prepareFields = ( fields: Record<string, ISetting> ): Record<string, ISetting> => Object.fromEntries(
    Object.entries( fields ).map( ( [ key, setting ] ) => [ key, {
        ...setting,
        customAttributes: {
            ...setting.customAttributes,
            isPressEnterToChange: false,
            autoComplete: setting.type === 'password' ? 'new-password' : 'off',
        },
        ...( setting.settings ? { settings: prepareFields( setting.settings ) } : {} ),
    } ] )
);

export const AddonSettings = ( { slug, onLoaded, onEmpty, onClose }: {
    slug: string;
    onLoaded: ( fields: Record<string, ISetting> ) => void;
    onEmpty: () => void;
    onClose: () => void;
} ) => {
    const [ panel, setPanel ] = useState<ISetting>();
    const [ saved, setSaved ] = useState<Record<string, any>>( {} );
    const [ changes, setChanges ] = useState<Record<string, any>>( {} );
    const [ loading, setLoading ] = useState( true );
    const [ saving, setSaving ] = useState( false );
    const [ error, setError ] = useState( '' );
    const [ success, setSuccess ] = useState( false );
    const [ retry, setRetry ] = useState( 0 );

    useEffect( () => {
        let cancelled = false;
        setLoading( true );
        setError( '' );
        Promise.all( [
            fetchAddonSettings(),
            apiFetch<{ noptin_options: Record<string, any> }>( { path: '/wp/v2/settings' } ),
        ] ).then( ( [ fields, options ] ) => {
            if ( cancelled ) return;
            onLoaded( fields );
            const settings = getAddonSettings( fields, slug );
            if ( !settings ) {
                onEmpty();
                return;
            }
            setPanel( settings );
            setSaved( options.noptin_options || {} );
        } ).catch( ( err ) => {
            if ( !cancelled ) setError( err.message || __( 'Could not load settings.', 'newsletter-optin-box' ) );
        } ).finally( () => {
            if ( !cancelled ) setLoading( false );
        } );
        return () => { cancelled = true; };
    }, [ slug, retry ] );

    const save = async () => {
        setSaving( true );
        setError( '' );
        setSuccess( false );
        try {
            const current = await apiFetch<{ noptin_options: Record<string, any> }>( { path: '/wp/v2/settings' } );
            const result = await apiFetch<{ noptin_options: Record<string, any> }>( {
                path: '/wp/v2/settings', method: 'POST', data: { noptin_options: { ...current.noptin_options, ...changes } },
            } );
            setSaved( result.noptin_options );
            setChanges( {} );
            setSuccess( true );
            // Connection status and available remote lists can change after saving credentials.
            const fields = await fetchAddonSettings();
            onLoaded( fields );
            setPanel( getAddonSettings( fields, slug ) );
        } catch ( err ) {
            setError( err.message || __( 'Could not save or refresh settings.', 'newsletter-optin-box' ) );
        } finally {
            setSaving( false );
        }
    };

    if ( loading ) return <Spinner />;

    return (
        <form autoComplete="off" className="noptin-addon-settings" onSubmit={ ( event ) => {
            event.preventDefault();
            if ( !saving && Object.keys( changes ).length ) save();
        } }>
        <VStack spacing={ 4 }>
            { error && <Notice status="error" isDismissible={ false }>{ error }</Notice> }
            { ( !panel || ( error && !Object.keys( changes ).length ) ) && <Button variant="secondary" onClick={ () => setRetry( retry + 1 ) }>{ __( 'Retry', 'newsletter-optin-box' ) }</Button> }
            { success && <Notice status="success" isDismissible={ false }>{ __( 'Settings saved.', 'newsletter-optin-box' ) }</Notice> }
            { panel?.description && <p>{ panel.description }</p> }
            { panel?.help_url && <Button variant="link" href={ panel.help_url } target="_blank" rel="noopener noreferrer">{ __( 'View integration guide', 'newsletter-optin-box' ) }</Button> }
            <fieldset disabled={ saving } style={ { border: 0, margin: 0, padding: 0 } }>
                <VStack spacing={ 4 }>
                    { Object.entries( prepareFields( panel?.settings || {} ) ).map( ( [ key, setting ] ) => (
                        <Setting key={ key } settingKey={ key } setting={ setting }
                            saved={ { ...saved, ...changes } }
                            setAttributes={ ( values ) => {
                                setChanges( ( previous ) => ( { ...previous, ...values } ) );
                                setSuccess( false );
                            } } />
                    ) ) }
                </VStack>
            </fieldset>
            <div className="noptin-addon-settings__actions">
                { panel && <Button type="submit" variant="primary" isBusy={ saving } disabled={ saving || !Object.keys( changes ).length }>{ __( 'Save Settings', 'newsletter-optin-box' ) }</Button> }
                <Button type="button" variant="secondary" disabled={ saving } onClick={ onClose }>{ __( 'Back to add-ons', 'newsletter-optin-box' ) }</Button>
            </div>
        </VStack>
        </form>
    );
};
